local ActionDarkDreamMainLevelNewNormalCell = Class('ActionDarkDreamMainLevelNewNormalCell')
local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
local UIModule = CS.Engine.UI.UIModule

function ActionDarkDreamMainLevelNewNormalCell:__init()

end

function ActionDarkDreamMainLevelNewNormalCell:__delete()

end

function ActionDarkDreamMainLevelNewNormalCell:Awake()
	self:InitStarList()
	self:AddUIClick()
end

function ActionDarkDreamMainLevelNewNormalCell:AddUIClick()
	SetButtonAction(self.BtnNode.gameObject,Bind(self,self.OnBtnNodeClick))
end

function ActionDarkDreamMainLevelNewNormalCell:OnBtnNodeClick()
	if checkNumber(self.data.passed) == 1 then
		self:ClickCallBack()
		UIModule.OpenDialog({ id = Constants.UITypeIds.ActionDarkDreamLevelDetails, parameters = { data = self.data,groupId = self.groupId}},{ { id = Constants.UITypeIds.ActionDarkDreamMainDialog } })
		return
	end
	
	if self.isUnLock then
		self:ClickCallBack()
		UIModule.OpenDialog({ id = Constants.UITypeIds.ActionDarkDreamLevelDetails, parameters = { data = self.data,groupId = self.groupId}},{ { id = Constants.UITypeIds.ActionDarkDreamMainDialog } })
	else
		GameUtils.Toast(localize("请通关前置关卡"))
	end
end

function ActionDarkDreamMainLevelNewNormalCell:ClickCallBack()
	if not isNull(self.clickCallBack) then
		self.clickCallBack()
	end
end

function ActionDarkDreamMainLevelNewNormalCell:InitStarList()
	if self.StarList then
		local env = CfUtils.GetLuaScr(self.StarList,"Game.UI.FightReady.ChaoticRecall.ActionDarkDreamStarRoot")
		if not isNull(env) then
			self.starEnv = env
		end
		CfUtils.SetActive(self.StarList.gameObject,true)
	end
end

function ActionDarkDreamMainLevelNewNormalCell:RefreshShow(data, groupId, index, callBack)
	CfUtils.SetActive(self.UIFX_LoopGlow.gameObject,false)
	self.data = data
	self.groupId = groupId
	self.index = index
	self.clickCallBack = callBack
	
	local nodeVo = ChaoticRecallUtils.GetChaoticRecallNodeVo(self.data.id)
	self.nodeVo = nodeVo
	self:SetHardNode()
	local num = self.data.nodeId
	if checkNumber(num) < 10 then
		num = string.format("0%s",num)
	end
	
	local isPass = checkNumber(self.data.passed) == 1
	
	if isPass then
		CfUtils.SetUISwitchImage(self.ImgBg,2)
		CfUtils.SetActive(self.StatusLock.gameObject,false)
		CfUtils.SetActive(self.StatusUnlock.gameObject,true)
		CfUtils.FillText(self.TextNumber,num)
		self:RefreshStarShow()
	else
		
		local isUnLock = checkNumber(nodeVo.unlockPlace) == 0 and true or ChaoticRecallUtils.GetIsPassById(nodeVo.groupId,nodeVo.unlockPlace)
		self.isUnLock = isUnLock
		CfUtils.SetActive(self.StatusLock.gameObject,not isUnLock)
		CfUtils.SetActive(self.StatusUnlock.gameObject,isUnLock)
		CfUtils.SetUISwitchImage(self.ImgBg,isUnLock and 2 or 1)
		if isUnLock then
			CfUtils.FillText(self.TextNumber,num)
			self:RefreshStarShow()
		else
			CfUtils.FillText(self.TextNumber,num)
		end
	end
end

function ActionDarkDreamMainLevelNewNormalCell:SetHardNode()
	local isHardNode = not isNull(self.nodeVo.hardLevels)
	CfUtils.SetActive(self.EmptyBox.gameObject,not isHardNode)
	CfUtils.SetActive(self.HardStarList.gameObject,isHardNode)
	if isHardNode then
		for i = 1, 2 do
			local addStar = self["AddStar"..i]
			if addStar then
				local light = addStar.transform:Find("ImgLight")
				local isPass = self.data.hardPassed[i] == 1
				CfUtils.SetActive(light.gameObject,isPass)
			end
		end
	end
end

function ActionDarkDreamMainLevelNewNormalCell:RefreshStarShow()
	self.starEnv:RefreshStarShow(self.data.starCompleted)
end

function ActionDarkDreamMainLevelNewNormalCell:SetCallBack()

end

function ActionDarkDreamMainLevelNewNormalCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return ActionDarkDreamMainLevelNewNormalCell